import{_ as r,C as l,c as n,o as a,a3 as s,G as o}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Skills and resume","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/employees/skills-and-resume.md","filePath":"master/human-resources/employees/employees/skills-and-resume.md","lastUpdated":1793074831000}'),i={name:"master/human-resources/employees/employees/skills-and-resume.md"};function g(d,e,h,p,m,c){const t=l("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=s('<h1 id="skills-and-resume" tabindex="-1">Skills and resume <a class="header-anchor" href="#skills-and-resume" aria-label="Permalink to &quot;Skills and resume&quot;">​</a></h1><p>Skills say what a person can do. Resume lines say where they have worked and studied. Both are kept on the employee record, so you can search for the right person later and see their background on the profile.</p><blockquote><p><strong>In simple words:</strong> Skills are abilities with a level. Resume lines are jobs and studies with dates.</p></blockquote><p>Open <code>Employees → Employees</code>, click <strong>View</strong> on an employee, then <strong>Manage Skills</strong> or <strong>Manage Resumes</strong>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Skills come from <a href="./../setup/skill-types.html">Skill types</a>. A skill type holds skills and levels. Set them up before you add a skill to an employee.</p></div><h2 id="manage-skills" tabindex="-1">Manage skills <a class="header-anchor" href="#manage-skills" aria-label="Permalink to &quot;Manage skills&quot;">​</a></h2><p>The page title is &quot;Manage {Name} Skills&quot;, for example <strong>Manage Priya Sharma Skills</strong>. The table is not grouped at first. <strong>Group by</strong> offers <strong>Skill Type</strong> and <strong>Skill</strong>. The <strong>Add Skill</strong> button is at the top right.</p><p>Columns are <strong>Skill Type</strong>, <strong>Skill</strong>, <strong>Skill Level</strong>, <strong>Level Percent</strong> and <strong>Created By</strong>. Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong> on the right. Select rows to use <strong>Delete selected</strong>.</p>',8)),o(t,{src:"/images1/employees/emp_skills_table.png",alt:"Manage skills table grouped by Skill Type, with the group Skill Type: Soft Skills, the columns, and a yellow 50.00% bar for Communication"}),e[1]||(e[1]=s('<h3 id="add-a-skill" tabindex="-1">Add a skill <a class="header-anchor" href="#add-a-skill" aria-label="Permalink to &quot;Add a skill&quot;">​</a></h3><ol><li>Click <strong>Add Skill</strong>. The <strong>Create Employee Skill</strong> window opens.</li><li>Choose a <strong>Skill Type</strong> from the radio list. <strong>Languages</strong> is selected first.</li><li>Choose a <strong>Skill</strong>. The list shows only skills of that type.</li><li>Choose a <strong>Skill Level</strong>. The list shows only levels of that type.</li><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong> for more. A <strong>Skill created</strong> notification says <strong>The skill has been created successfully.</strong></li></ol><p><strong>Skill</strong> and <strong>Skill Level</strong> are dropdowns that change with the <strong>Skill Type</strong>. All three fields are required.</p><p>Example with <strong>Languages</strong>: pick <strong>English</strong> and level <strong>B2</strong>. Levels run <strong>A1</strong>, <strong>A2</strong>, <strong>B1</strong>, <strong>B2</strong>, <strong>C1</strong>, <strong>C2</strong>.</p><p>Example for Priya Sharma with <strong>Soft Skills</strong>: pick <strong>Communication</strong> and level <strong>Intermediate</strong>. Soft Skills levels run <strong>Beginner</strong> (15%), <strong>Elementary</strong> (25%), <strong>Intermediate</strong> (50%), <strong>Advanced</strong> (80%) and <strong>Expert</strong> (100%).</p>',5)),o(t,{src:"/images1/employees/emp_skills_add.png",alt:"Create Employee Skill window with Soft Skills, Communication and Intermediate chosen"}),e[2]||(e[2]=s('<h3 id="level-and-proficiency-bar" tabindex="-1">Level and proficiency bar <a class="header-anchor" href="#level-and-proficiency-bar" aria-label="Permalink to &quot;Level and proficiency bar&quot;">​</a></h3><p>Every level has a percent, set in the skill type. <strong>Intermediate</strong> is 50.00%. The bar is yellow and reads 50.00%. The profile shows it next to the level badge. A higher level fills more of the bar.</p><h2 id="manage-resumes" tabindex="-1">Manage resumes <a class="header-anchor" href="#manage-resumes" aria-label="Permalink to &quot;Manage resumes&quot;">​</a></h2><p>The page title is &quot;Manage {Name} Resumes&quot;. A search box finds lines by text.</p><p>Columns are <strong>Title</strong>, <strong>Start Date</strong>, <strong>End Date</strong>, <strong>Display Type</strong>, <strong>Description</strong>, <strong>Attachments</strong> and <strong>Created By</strong>. There is no <strong>Type</strong> column. Dates in the table look like <strong>Jan 1, 2020</strong>.</p>',5)),o(t,{src:"/images1/employees/emp_resumes_table.png",alt:"Manage resumes table with the Stock Controller and B.Com lines, showing title, dates and display type"}),e[3]||(e[3]=s('<h3 id="add-a-resume-line" tabindex="-1">Add a resume line <a class="header-anchor" href="#add-a-resume-line" aria-label="Permalink to &quot;Add a resume line&quot;">​</a></h3><ol><li>Click <strong>Add Resume</strong>. The <strong>Create Employee Resume</strong> window opens.</li><li>Choose a <strong>Type</strong> from the searchable list: <strong>Education</strong> or <strong>Experience</strong>. A plus button next to it adds a type.</li><li>Type the <strong>Title</strong>. This is required.</li><li>Pick <strong>Start Date</strong> in the date picker. This is required. Pick <strong>End Date</strong> if the line has ended. You cannot type a date.</li><li>Leave <strong>Display Type</strong> as <strong>Classic</strong>. It is the only option.</li><li>Write a short <strong>Description</strong>.</li><li>Click <strong>Add Attachment</strong> to upload a certificate or letter. Each attachment needs a file.</li><li>Click <strong>Create</strong>. A <strong>Resume created</strong> notification says <strong>The resume has been created successfully.</strong></li></ol><p>Example: Type <strong>Experience</strong>, Title <strong>Stock Controller at Metro Traders</strong>, 2020 to 2024. Then add Type <strong>Education</strong>, Title <strong>B.Com, Pune University</strong>, 2016 to 2019.</p>',3)),o(t,{src:"/images1/employees/emp_resumes_add.png",alt:"Create Employee Resume window filled with Stock Controller at Metro Traders"}),e[4]||(e[4]=s('<h2 id="how-the-profile-shows-them" tabindex="-1">How the profile shows them <a class="header-anchor" href="#how-the-profile-shows-them" aria-label="Permalink to &quot;How the profile shows them&quot;">​</a></h2><p>On the profile, open the <strong>Resume</strong> tab.</p><ul><li>The left card lists the resume lines.</li><li>Each line shows its dates as <strong>01/2020 - 12/2024</strong>, title and description. A line with no end date shows <strong>Present</strong> as the end.</li><li>The right card lists skills with a level badge and bar.</li></ul>',3)),o(t,{src:"/images1/employees/emp_resume_tab_result.png",alt:"Resume tab of Priya Sharma with Experience and Education lines and the Communication skill"}),e[5]||(e[5]=s('<h2 id="skills-across-the-company" tabindex="-1">Skills across the company <a class="header-anchor" href="#skills-across-the-company" aria-label="Permalink to &quot;Skills across the company&quot;">​</a></h2><p>To see every employee&#39;s skills in one table, open <code>Employees → Reportings → Skills</code>. See <a href="./../reporting/skills-report.html">Skills report</a>. The employee list also has a <strong>Skills</strong> filter.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../setup/skill-types.html">Skill types</a></li><li><a href="./employee-profile.html">Employee profile</a></li><li><a href="./employee-list.html">Employee list</a></li><li><a href="./../reporting/skills-report.html">Skills report</a></li></ul>',4))])}const y=r(i,[["render",g]]);export{k as __pageData,y as default};
